-- Only for the isolated local test cluster; never run against VOTRIX production.
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN CREATE ROLE service_role; END IF; END $$;
CREATE TABLE users(id uuid PRIMARY KEY,account_status text NOT NULL DEFAULT 'active',role text NOT NULL DEFAULT 'participant');
CREATE TABLE organizations(id uuid PRIMARY KEY,organizer_id uuid REFERENCES users);
CREATE TABLE events(id uuid PRIMARY KEY,organization_id uuid REFERENCES organizations,event_type text DEFAULT 'competition_scoring',status text DEFAULT 'draft',scoring_enabled boolean DEFAULT false);
CREATE TABLE event_participants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid REFERENCES events,user_id uuid REFERENCES users,participant_type text DEFAULT 'COMPETITION_JUDGE',is_active boolean DEFAULT true,judge_role text DEFAULT 'judge',UNIQUE(event_id,user_id));
CREATE TABLE competition_divisions(id uuid PRIMARY KEY,event_id uuid REFERENCES events);
CREATE TABLE competition_categories(id uuid PRIMARY KEY,event_id uuid REFERENCES events);
CREATE TABLE competition_rounds(id uuid PRIMARY KEY,event_id uuid REFERENCES events,name text,weight numeric DEFAULT 0,display_order integer DEFAULT 0,created_at timestamptz DEFAULT now(),finalized_at timestamptz);
CREATE TABLE competition_contestants(id uuid PRIMARY KEY,event_id uuid REFERENCES events,division_id uuid REFERENCES competition_divisions,name text,contestant_number integer DEFAULT 1,photo text);
CREATE TABLE competition_criteria(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid REFERENCES events,name text,percentage numeric,min_score numeric,max_score numeric,display_order integer DEFAULT 0);
CREATE TABLE competition_minor_criteria(id uuid PRIMARY KEY,criteria_id uuid REFERENCES competition_criteria,event_id uuid REFERENCES events);
CREATE TABLE competition_round_criteria(round_id uuid REFERENCES competition_rounds,criteria_id uuid REFERENCES competition_criteria,UNIQUE(round_id,criteria_id));
CREATE TABLE competition_judge_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),participant_id uuid REFERENCES event_participants,scope text,scope_id uuid);
CREATE TABLE competition_round_contestants(round_id uuid REFERENCES competition_rounds,contestant_id uuid REFERENCES competition_contestants,UNIQUE(round_id,contestant_id));
CREATE TABLE competition_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid REFERENCES events,status text,current_round_id uuid REFERENCES competition_rounds,active_contestant_id uuid REFERENCES competition_contestants,current_division_id uuid REFERENCES competition_divisions,active_contestant_ids jsonb,current_contestant_order integer DEFAULT 0,contestant_order uuid[],started_at timestamptz,paused_at timestamptz,completed_at timestamptz,CONSTRAINT competition_sessions_unique_active UNIQUE(event_id,status));
CREATE TABLE competition_session_judge_scores(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid REFERENCES competition_sessions,event_id uuid REFERENCES events,round_id uuid REFERENCES competition_rounds,contestant_id uuid REFERENCES competition_contestants,judge_id uuid REFERENCES users,participant_id uuid REFERENCES event_participants,scores jsonb DEFAULT '{}',locked_criteria jsonb DEFAULT '[]',is_locked boolean DEFAULT false,locked_at timestamptz,updated_at timestamptz DEFAULT now());
CREATE TABLE competition_scores(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),judge_id uuid REFERENCES users,participant_id uuid REFERENCES event_participants,contestant_id uuid REFERENCES competition_contestants,criteria_id uuid REFERENCES competition_criteria,minor_criteria_id uuid REFERENCES competition_minor_criteria,round_id uuid REFERENCES competition_rounds,category_id uuid REFERENCES competition_categories,division_id uuid REFERENCES competition_divisions,score numeric);
CREATE TABLE competition_deductions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid REFERENCES events,contestant_id uuid REFERENCES competition_contestants,round_id uuid REFERENCES competition_rounds,amount numeric,status text DEFAULT 'active',reason text,applied_by_user_id uuid,authority_type text);
CREATE TABLE competition_result_calculations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid REFERENCES events,session_id uuid REFERENCES competition_sessions,round_id uuid REFERENCES competition_rounds,status varchar(16) CONSTRAINT competition_result_calculations_status_check CHECK(status IN('calculated','finalized','published','superseded')),configuration_snapshot jsonb,result_snapshot jsonb,created_by uuid,created_at timestamptz DEFAULT now(),finalized_by uuid,finalized_at timestamptz,published_by uuid,published_at timestamptz);
CREATE TABLE audit_logs(id uuid DEFAULT gen_random_uuid(),user_id uuid,action text,entity text,entity_id uuid,details jsonb);
